import csv
import io
import posixpath
from datetime import date, datetime
from decimal import Decimal, ROUND_HALF_UP

def merge(p):
    out=[]
    for start,end in sorted(p):
        if out and start <= out[-1][1]: out[-1][1]=max(out[-1][1],end)
        else: out.append([start,end])
    return out

def overlap(p):
    return max(0,min(p[0][1],p[1][1])-max(p[0][0],p[1][0]))

def due(p):
    today=date.fromisoformat(p['today'])
    return [t['id'] for t in p['tasks'] if date.fromisoformat(t['due']) <= today]

