import posixpath
from datetime import date, datetime
from decimal import Decimal, ROUND_HALF_UP

def slots(p):
    return [[s,s+p['length']] for s in range(p['start'],p['end']-p['length']+1,p['length'])]

def elapsed(p):
    return int((datetime.fromisoformat(p['end']).replace(tzinfo=None)-datetime.fromisoformat(p['start']).replace(tzinfo=None)).total_seconds()//60)

